        public StockItem[] Stocks {get;}=Enumerable.Range(1,8).Select(i=>new StockItem(i.ToString("D6"),"병렬검사 "+i,Exchange.KRX,i.ToString("D6"),"검사")).ToArray();
        public int Active,MaxActive;
        private async Task Delay(CancellationToken token){var active=Interlocked.Increment(ref Active);int seen;do{seen=MaxActive;if(seen>=active)break;}while(Interlocked.CompareExchange(ref MaxActive,active,seen)!=seen);try{await Task.Delay(70,token);}finally{Interlocked.Decrement(ref Active);}}
        public Task<IReadOnlyList<StockItem>> Search(string name,string region,CancellationToken token)=>Task.FromResult<IReadOnlyList<StockItem>>(Stocks);
        public Task<IReadOnlyList<StockItem>> Universe(string region,int perExchange,CancellationToken token)=>Task.FromResult<IReadOnlyList<StockItem>>(Stocks.Take(perExchange).ToArray());
        public async Task<StockItem> Describe(StockItem stock,CancellationToken token){await Delay(token);return stock;}
        public async Task<BarDataset> History(StockItem stock,CancellationToken token){await Delay(token);return new(stock,Enumerable.Range(0,40).Select(i=>DailyBar(i,100-i%6)).ToArray(),"PERFORMANCE_FIXTURE",DateTimeOffset.UtcNow);}
        public async Task<DailySecurityStatus?> CurrentSecurity(StockItem stock,CancellationToken token){await Delay(token);return null;}
        public async Task<CurrentMarketSnapshot> Current(StockItem stock,CancellationToken token){await Delay(token);var now=DateTimeOffset.UtcNow;return new(stock,new(stock.Name,95,-5,-5,now,"OPEN"),now,100,101,94,1000,95000,"PERFORMANCE_FIXTURE",TimeSpan.FromSeconds(7));}
    }
